#!/bin/sh
ssh_menu(){ while :; do c=$(ui_menu SSH 'OpenSSH server, client, keys, and diagnostics.' status 'Show server status' install 'Install OpenSSH' server 'Edit sshd_config' client 'Edit client config' port 'Set server port' auth 'Authentication policy' root 'Root login policy' keepalive 'Configure keepalives' keys 'Generate user key' authorized 'Edit authorized_keys' hostkeys 'Generate missing host keys' test 'Validate server configuration' restart 'Restart SSH service') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in status) ui_msg SSH "sshd: $(service_state sshd)\nssh: $(service_state ssh)";; install) case $PKG_MGR in apt) run_capture SSH pkg_install openssh-client openssh-server;; *) run_capture SSH pkg_install openssh;; esac;; server) edit_file /etc/ssh/sshd_config;; client) mkdir -p "$CURRENT_HOME/.ssh"; ensure_template ssh_config "$CURRENT_HOME/.ssh/config";; port) p=$(ui_input SSH 'Port:' 2222) || continue; sshd_set Port "$p";; auth) c2=$(ui_menu Auth 'Authentication policy.' password 'Enable passwords' keys 'Keys only' both 'Passwords and keys') || continue; case $c2 in password) sshd_set PasswordAuthentication yes;; keys) sshd_set PasswordAuthentication no; sshd_set PubkeyAuthentication yes;; both) sshd_set PasswordAuthentication yes; sshd_set PubkeyAuthentication yes;; esac;; root) v=$(ui_menu Root 'PermitRootLogin:' yes yes prohibit-password prohibit-password no no) || continue; sshd_set PermitRootLogin "$v";; keepalive) sshd_set ClientAliveInterval 60; sshd_set ClientAliveCountMax 3; sshd_set TCPKeepAlive yes;; keys) t=$(ui_menu Key 'Key type:' ed25519 ed25519 rsa rsa ecdsa ecdsa) || continue; mkdir -p "$CURRENT_HOME/.ssh"; ssh-keygen -t "$t" -f "$CURRENT_HOME/.ssh/id_$t";; authorized) mkdir -p "$CURRENT_HOME/.ssh"; chmod 700 "$CURRENT_HOME/.ssh"; edit_file "$CURRENT_HOME/.ssh/authorized_keys"; chmod 600 "$CURRENT_HOME/.ssh/authorized_keys";; hostkeys) run_capture Hostkeys as_root ssh-keygen -A;; test) run_capture Validation as_root sshd -t;; restart) service_restart sshd || service_restart ssh;; esac; done; }
sshd_set(){ f=/etc/ssh/sshd_config; [ -e "$f" ] || write_file "$f" 600 ''; backup_file "$f"; if grep -Eq "^[#[:space:]]*$1[[:space:]]" "$f"; then as_root sed -i "s/^[#[:space:]]*$1[[:space:]].*/$1 $2/" "$f"; else printf '%s %s\n' "$1" "$2"|as_root tee -a "$f" >/dev/null; fi; }
